import sys
import heapq

def main():
    import sys
    import heapq

    def readints():
        return list(map(int, sys.stdin.readline().split()))

    n, c = readints()
    a = readints()

    def calculate_value(subarray):
        k = len(subarray)
        exclude_count = k // c
        if exclude_count == 0:
            return sum(subarray)
        heap = []
        for x in subarray:
            heapq.heappush(heap, x)
            if len(heap) > exclude_count:
                heapq.heappop(heap)
        return sum(heapq.heappop(heap) for _ in range(len(heap)))

    min_sum = float('inf')
    current_sum = 0
    current_subarray = []

    for i in range(n):
        current_subarray.append(a[i])
        current_sum += a[i]

        if i == n - 1 or current_sum >= calculate_value(current_subarray):
            min_sum = min(min_sum, current_sum - calculate_value(current_subarray))
            current_sum -= calculate_value(current_subarray)
            current_subarray = []

    print(min_sum)

if __name__ == "__main__":
    main()
